59	/**
60	 * Load configuration from environment variables
61	 */
62	function loadEnvConfig(): Partial<SystemConfig> {
63	  const config: Partial<SystemConfig> = {};
64	
65	  // Orchestrator settings
66	  if (process.env.CLAUDE_FLOW_MAX_AGENTS) {
67	    config.orchestrator = {
68	      ...defaultSystemConfig.orchestrator,
69	      lifecycle: {
70	        ...defaultSystemConfig.orchestrator.lifecycle,
71	        maxConcurrentAgents: parseInt(process.env.CLAUDE_FLOW_MAX_AGENTS, 10),
72	      },
73	    };
74	  }
75	
76	  // Data directory
77	  if (process.env.CLAUDE_FLOW_DATA_DIR) {
78	    config.orchestrator = {
79	      ...config.orchestrator,
80	      ...defaultSystemConfig.orchestrator,
81	      session: {
82	        ...defaultSystemConfig.orchestrator.session,
83	        dataDir: process.env.CLAUDE_FLOW_DATA_DIR,
84	      },
85	    };
86	  }
87	
88	  // Memory type
89	  if (process.env.CLAUDE_FLOW_MEMORY_TYPE) {
90	    const memoryType = process.env.CLAUDE_FLOW_MEMORY_TYPE as NonNullable<SystemConfig['memory']>['type'];
91	    if (['sqlite', 'agentdb', 'hybrid', 'redis', 'memory'].includes(memoryType)) {
92	      config.memory = {
93	        ...(defaultSystemConfig.memory ?? { type: 'hybrid' }),
94	        type: memoryType,
95	      };
96	    }
97	  }
98	
99	  // MCP transport
100	  const defaultMcp = defaultSystemConfig.mcp ?? { name: 'claude-flow', version: '3.0.0', transport: { type: 'stdio' as const } };
101	  if (process.env.CLAUDE_FLOW_MCP_TRANSPORT) {
102	    const transport = process.env.CLAUDE_FLOW_MCP_TRANSPORT as 'stdio' | 'http' | 'websocket';
103	    if (['stdio', 'http', 'websocket'].includes(transport)) {
104	      config.mcp = {
105	        ...defaultMcp,
106	        transport: {
107	          ...defaultMcp.transport,
108	          type: transport,
109	        },
110	      };
111	    }
112	  }
113	
114	  if (process.env.CLAUDE_FLOW_MCP_PORT) {
115	    config.mcp = {
116	      ...config.mcp,
117	      ...defaultMcp,
118	      transport: {
119	        ...config.mcp?.transport,
120	        ...defaultMcp.transport,
121	        port: parseInt(process.env.CLAUDE_FLOW_MCP_PORT, 10),
122	      },
123	    };
124	  }
125	
126	  // Swarm topology
127	  const defaultSwarm = defaultSystemConfig.swarm ?? { topology: 'hierarchical-mesh' as const, maxAgents: 20 };
128	  if (process.env.CLAUDE_FLOW_SWARM_TOPOLOGY) {
129	    const topology = process.env.CLAUDE_FLOW_SWARM_TOPOLOGY as NonNullable<SystemConfig['swarm']>['topology'];
130	    if (['hierarchical', 'mesh', 'ring', 'star', 'adaptive', 'hierarchical-mesh'].includes(topology)) {
131	      config.swarm = {
132	        ...defaultSwarm,
133	        topology,
134	      };
135	    }
136	  }
137	
138	  return config;
139	}
